use biome_console::markup;
use biome_diagnostics::Severity;
use biome_html_syntax::AnyHtmlElement;
use biome_rowan::{AstNode, TextRange};
use biome_rule_options::use_iframe_sandbox::UseIframeSandboxOptions;

declare_lint_rule! {
    /// Enforces the use of the `sandbox` attribute on `<iframe>` elements.
    ///
    /// The `sandbox` attribute enables an extra set of restrictions for the content
    /// embedded in an `<iframe>`, protecting the host page against malicious scripts
    /// and other security threats. An `<iframe>` without a `sandbox` attribute runs
    /// the embedded content with no additional restrictions.
    ///
    /// Adding an empty `sandbox` attribute applies the strictest set of restrictions,
    /// which can then be relaxed on a case-by-case basis.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```html,expect_diagnostic
    /// <iframe src="https://example.com"></iframe>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <iframe sandbox src="https://example.com"></iframe>
    /// ```
    ///
    /// ```html
    /// <iframe sandbox="allow-scripts" src="https://example.com"></iframe>
    /// ```
    ///
    /// ## Resources
    ///
    /// - [MDN: The Inline Frame element](https://developer.mozilla.org/en-US/docs/Web/HTML/Element/iframe)
    ///
    pub UseIframeSandbox {
        version: "next",
        name: "useIframeSandbox",
        language: "html",
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for UseIframeSandbox {
    type Query = Ast<AnyHtmlElement>;
    type State = TextRange;
    type Signals = Option<Self::State>;
    type Options = UseIframeSandboxOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let element = ctx.query();
        let file_extension = ctx.file_path().extension()?;

        if !is_iframe_element(element, file_extension) {
            return None;
        }

        // Any `sandbox` attribute (boolean, empty, or with a value) satisfies the rule.
        if element.find_attribute_by_name("sandbox").is_some() {
            return None;
        }

        Some(element.syntax().text_trimmed_range())
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state,
                markup! {
                    "Iframe doesn't have the sandbox attribute."
                },
            )
            .note(markup! {
                "The sandbox attribute enables an extra set of restrictions for the content in the iframe, protecting against malicious scripts and other security threats."
            })
            .note(markup! {
                "Provide a sandbox attribute when using iframe elements."
            }),
        )
    }
}

/// Checks if the element is an iframe element.
///
/// - In `.html` files, matching is case-insensitive.
/// - In component-based frameworks, only lowercase `iframe` is matched to avoid flagging custom components like `<Iframe>`.
fn is_iframe_element(element: &AnyHtmlElement, file_extension: &str) -> bool {
    element.name().is_some_and(|token_text| {
        let is_html_file = file_extension == "html";
        if is_html_file {
            token_text.eq_ignore_ascii_case("iframe")
        } else {
            token_text == "iframe"
        }
    })
}
